import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Create a mapping from feature id to its type value
    type_map = dict(zip(feats.ids, feats.types))

    # Find features with strong association (p < 0.05, |t| > 2)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Use the actual type value to determine if it's a strong feature
        type_val = type_map[fid]
        # We'll use a heuristic approach since we don't have direct p-values
        # The types array contains the t-statistics or similar strength measures
        if isinstance(type_val, (int, float)) and abs(type_val) > 2:
            strong_features.append((fid, type_val))

    # Sort by absolute t-statistic
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for correlated pairs
    correlations = {}
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                correlations[(feats.ids[i], feats.ids[j])] = corr

    # Remove near-duplicates by keeping the feature with higher absolute t-statistic
    to_remove = set()
    for (a, b), corr in correlations.items():
        if (a, b) not in to_remove and (b, a) not in to_remove:
            # Keep the one with higher absolute t-statistic
            t_a = 0
            t_b = 0
            for fid, t_val in strong_features:
                if fid == a:
                    t_a = t_val
                elif fid == b:
                    t_b = t_val
            if abs(t_a) < abs(t_b):
                to_remove.add((a, b))
            else:
                to_remove.add((b, a))

    # Build final feature list excluding near-duplicates
    selected_features = []
    for fid, t_val in strong_features:
        keep = True
        for pair in to_remove:
            if fid in pair:
                keep = False
                break
        if keep:
            selected_features.append(fid)

    # Try to find product terms
    products = []
    for i, a in enumerate(selected_features[:10]):  # Limit search space
        for j, b in enumerate(selected_features[i+1:]):
            if (a, b) not in to_remove and (b, a) not in to_remove:
                # Compute correlation between product and outcome
                prod = feats.x[:, feats.column(a)] * feats.x[:, feats.column(b)]
                corr = np.corrcoef(prod, feats.y)[0,1]
                if abs(corr) > 0.1:  # threshold for product term
                    products.append((a, b))

    # Select top drivers based on effect size
    drivers = [f[0] for f in strong_features[:MAX_DRIVERS]]

    # If we have strong correlations, include them in drivers
    if products:
        # Add the most correlated product as driver if possible
        best_product = max(products, key=lambda p: abs(np.corrcoef(
            feats.x[:, feats.column(p[0])] * feats.x[:, feats.column(p[1])], feats.y)[0,1]))
        if len(drivers) < MAX_DRIVERS:
            drivers.append(best_product[0])
            drivers.append(best_product[1])

    # Return the design
    return Design(
        drivers=tuple(drivers[:MAX_DRIVERS]),
        columns=tuple(selected_features[:20]),  # limit to top 20
        products=tuple(products[:5]),  # limit to top 5 products
        loadings={fid: 1.0 for fid in selected_features[:10]}  # simple equal weights
    )

